type Status = "presente" | "vacaciones" | "licencia" | "permiso" | "compensatorio";
type DayRecord = { guardId:number; date:string; typeId:number|null };
const STATUS: Record<Status, {label:string; short:string; color:string; bg:string; code:string; icon:any; factor:number}> = {
  presente: { label:"Presente", short:"✓", code:"P", color:"#16745f", bg:"#dff5ec", icon:UserRound, factor:0 },
  vacaciones: { label:"Vacaciones", short:"V", code:"V", color:"#3172c6", bg:"#e3efff", icon:Umbrella, factor:1 },
  licencia: { label:"Licencia médica", short:"L", code:"S", color:"#d55454", bg:"#ffe5e3", icon:Stethoscope, factor:0 },
  permiso: { label:"Permiso / medio día", short:"PM", code:"HA", color:"#c46a16", bg:"#fff0d5", icon:Timer, factor:.5 },
  compensatorio: { label:"Día libre por compensación", short:"L", code:"L", color:"#7552b8", bg:"#eee7ff", icon:BriefcaseBusiness, factor:0 },
};
const ADMIN_DAY = { label:"Día administrativo", short:"A", code:"A", color:"#16829a", bg:"#dcf1f5", icon:CalendarDays, factor:0 };
/** Horario por defecto de cada turno (modificable en la ficha del guardia). */
const SHIFT_HOURS = { dia: { start: "08:00", end: "20:00" }, tarde: { start: "14:00", end: "22:00" }, noche: { start: "20:00", end: "08:00" } } as const;
const OTHER_CAUSE = { label:"Otras causas", short:"O", code:"O", color:"#4f6178", bg:"#e6ebf1", icon:FileText, factor:0 };
/** Categoría visual de cada código (solo afecta colores; no cambia cómo se guarda la marcación). */
const causeCategory=(code:string):Status|null=>code==="V"?"vacaciones":["S","M"].includes(code)?"licencia":["HA","HP","Q","PM"].includes(code)?"permiso":code==="L"?"compensatorio":null;
const weekday = ["D","L","M","X","J","V","S"];
const pad=(n:number)=>String(n).padStart(2,"0");
const dateKey=(v:any)=>typeof v === "string" ? v.slice(0,10) : new Date(v).toISOString().slice(0,10);
const localKey=(d:Date)=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
function mondayOf(d:Date){ const x=new Date(d); const day=x.getDay()||7; x.setDate(x.getDate()-day+1); x.setHours(0,0,0,0); return x; }
function addDays(d:Date,n:number){const x=new Date(d);x.setDate(x.getDate()+n);return x;}
function isoWeek(d:Date){ const x=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())); const day=x.getUTCDay()||7; x.setUTCDate(x.getUTCDate()+4-day); const y=new Date(Date.UTC(x.getUTCFullYear(),0,1)); return Math.ceil((((x.getTime()-y.getTime())/86400000)+1)/7); }
function mondayFromIsoWeek(year:number, week:number){ const jan4=new Date(year,0,4); const first=mondayOf(jan4); return addDays(first,(week-1)*7); }
function initials(name:string){return name.split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase();}
function readableCauseColor(code:string,color:string){const strong:Record<string,string>={P:"#245fa3",V:"#2367a8",S:"#c23e3e",HA:"#a85f0c",HP:"#a85f0c",Q:"#8b5a12",PM:"#a85f0c",L:"#6b45a6",H:"#15805c",M:"#9b3278",X1:"#3e6657",X2:"#3e6657",X3:"#3e6657",X4:"#3e6657",X5:"#3e6657",X6:"#3e6657",X7:"#3e6657",X8:"#3e6657",X9:"#3e6657",X0:"#3e6657"};return strong[code]||"#355c52";}
function AdminDaysBar({info}:{info?:{left:number;total:number;periodStart:string;periodEnd:string}}){ if(!info)return null; const pct=Math.max(0,Math.min(100,info.left/info.total*100)); const tone=info.left<=0?"danger":info.left<=1?"warn":"good"; const fmt=(d:string)=>new Date(d+"T12:00:00").toLocaleDateString("es-CL",{day:"numeric",month:"short",year:"numeric"}); return <div className="vacation admin-days" title={`Año calendario: ${fmt(info.periodStart)} – ${fmt(info.periodEnd)} · ${info.total-info.left} usados`}><div className="vacation-line"><span>Días administrativos</span><strong className={tone}>{info.left<=0?"Agotados":`${info.left} de ${info.total}`}</strong></div><div className="progress"><i style={{width:`${pct}%`}} className={tone}/></div></div> }
function VacationBar({left,total}:{left:number;total:number}) { const pct=Math.max(0,Math.min(100,total?left/total*100:0)); const tone=left<=0?"danger":left<=4?"warn":"good"; return <div className="vacation"><div className="vacation-line"><span>Vacaciones restantes</span><strong className={tone}>{left} días</strong></div><div className="progress"><i style={{width:`${pct}%`}} className={tone}/></div></div> }

